            ignore_dirs: vec![
                PathBuf::from("/proc"),
                PathBuf::from("/dev"),
                PathBuf::from("/sys"),
                PathBuf::from("/run"),
            ],
            log_file: None,
        }
    }
}

#[derive(Debug)]
pub struct ParsedArgs {
    pub global: GlobalArgs,
    pub command: Command,
}

pub struct ClapError {
    pub msg: String,
    /// usage line to be shown in error messages; e.g. "dua [FLAGS]..." or
    /// "executable aggregate [OPTIONS] [INPUT]..."
    pub usage: String,
    pub help_hint: bool,
    pub exit_code: u8,
}

pub enum ArgResult {
    Parsed(ParsedArgs),
    /// Print this text to stdout and exit 0.
    Help(String),
    /// Print this text to stdout and exit 0.
    Version(String),
    Err(ClapError),
}

/// Accept and consume a positional INPUT. Each element is parsed as a PathBuf.
fn to_paths<I: IntoIterator<Item = OsString>>(it: I) -> Vec<PathBuf> {
    it.into_iter().map(PathBuf::from).collect()
}

/// Parse the command line. `argv` should include argv[0].
pub fn parse(argv: &[OsString], exe_basename: &str) -> ArgResult {
    use crate::cli::{usage_main, usage_sub, HELP_MAIN, HELP_MAIN_SHORT};

    let mut global = GlobalArgs::default();
    let mut it = argv.iter().skip(1).cloned().peekable();

    // First pass: consume global flags/options. Stop at the first non-option
    // which may be a subcommand name or positional INPUT.
    let mut positional: Vec<OsString> = Vec::new();
    let mut after_dashdash = false;
    // We collect positionals as we go so that subcommand detection is done
    // on the first positional. Subcommand detection happens once.
    let mut subcommand_detected: Option<String> = None;
    let mut explicit_ignore_dirs: Option<Vec<PathBuf>> = None;

    while let Some(arg) = it.next() {
        if after_dashdash {
            positional.push(arg);
            continue;
        }
        let a = match arg.to_str() {
            Some(s) => s.to_string(),
            None => {
                positional.push(arg);
                continue;
            }
        };
        if a == "--" {
            after_dashdash = true;
            continue;
        }
        // --help / -h handled globally
        if a == "--help" {
            return ArgResult::Help(HELP_MAIN.to_string());
        }
        if a == "-h" {
            return ArgResult::Help(HELP_MAIN_SHORT.to_string());
        }
        if a == "--version" || a == "-V" {
            return ArgResult::Version("dua 2.32.2".to_string());
        }
        // Handle long options
        if let Some(rest) = a.strip_prefix("--") {
            let (name, val) = match rest.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (rest.to_string(), None),
            };
            match name.as_str() {
                "threads" => {
                    let v = match val {
                        Some(v) => v,
                        None => match it.next() {
                            Some(x) => x.to_string_lossy().to_string(),
                            None => return err_missing_value("--threads <THREADS>", &usage_main()),
                        },
                    };
                    match v.parse::<usize>() {
                        Ok(n) => global.threads = n,
                        Err(e) => {
                            return ArgResult::Err(ClapError {
                                msg: format!(
                                    "error: invalid value '{}' for '--threads <THREADS>': {}",
                                    v, e
                                ),
                                usage: String::new(),
                                help_hint: true,
                                exit_code: 2,
                            });
                        }
                    }
                }
                "format" => {
                    let v = match val {
                        Some(v) => v,
                        None => match it.next() {
                            Some(x) => x.to_string_lossy().to_string(),
                            None => return err_missing_value("--format <FORMAT>", &usage_main()),
                        },
                    };
                    match Format::parse(&v) {
                        Some(f) => global.format = f,
                        None => {
                            return ArgResult::Err(ClapError {
                                msg: format!(
                                    "error: invalid value '{}' for '--format <FORMAT>'\n  [possible values: metric, binary, bytes, gb, gib, mb, mib]",
                                    v
                                ),
                                usage: String::new(),
                                help_hint: true,
                                exit_code: 2,
                            });
                        }
                    }
                }
                "apparent-size" => {
                    if val.is_some() {
                        return err_no_value("--apparent-size", &usage_main());
                    }
                    global.apparent_size = true;
                }
                "count-hard-links" => {
                    if val.is_some() {
                        return err_no_value("--count-hard-links", &usage_main());
                    }
                    global.count_hard_links = true;
                }
                "stay-on-filesystem" => {
                    if val.is_some() {
                        return err_no_value("--stay-on-filesystem", &usage_main());
                    }
                    global.stay_on_filesystem = true;
                }
                "ignore-dirs" => {
                    let v = match val {
                        Some(v) => v,
                        None => match it.next() {
                            Some(x) => x.to_string_lossy().to_string(),
                            None => {
                                return err_missing_value(
                                    "--ignore-dirs <IGNORE_DIRS>",
                                    &usage_main(),
                                )
                            }
                        },
                    };
                    explicit_ignore_dirs
                        .get_or_insert_with(Vec::new)
                        .push(PathBuf::from(v));
                }
                "log-file" => {
                    let v = match val {
                        Some(v) => v,
                        None => match it.next() {
                            Some(x) => x.to_string_lossy().to_string(),
                            None => {
                                return err_missing_value("--log-file <LOG_FILE>", &usage_main())
                            }
                        },
                    };
                    global.log_file = Some(PathBuf::from(v));
                }
                _ => {
                    return err_unexpected(&a, &usage_main());
                }
            }
            continue;
        }
        if let Some(rest) = a.strip_prefix('-') {
            // Short option group like -Af or -t 2 or -t2
            if rest.is_empty() {
                // Lone `-` treated as positional (stdin); match subcommand detection
                positional.push(arg);
                break;
            }
            // Parse short options; some take values
            let mut chars = rest.chars().peekable();
            while let Some(c) = chars.next() {
                match c {
                    'A' => global.apparent_size = true,
                    'l' => global.count_hard_links = true,
                    'x' => global.stay_on_filesystem = true,
                    'h' => return ArgResult::Help(HELP_MAIN_SHORT.to_string()),
                    'V' => return ArgResult::Version("dua 2.32.2".to_string()),
                    't' | 'f' | 'i' => {
                        // These take a value; either remaining chars after c,
                        // with optional `=`, or the next argv entry.
                        let mut v: String = chars.clone().collect();
                        // Consume all chars so we stop iterating
                        while chars.next().is_some() {}
                        if let Some(stripped) = v.strip_prefix('=') {
                            v = stripped.to_string();
                        }
                        if v.is_empty() {
                            v = match it.next() {
                                Some(x) => x.to_string_lossy().to_string(),
                                None => {
                                    let desc = match c {
                                        't' => "--threads <THREADS>",
                                        'f' => "--format <FORMAT>",
                                        'i' => "--ignore-dirs <IGNORE_DIRS>",
                                        _ => unreachable!(),
                                    };
                                    return err_missing_value(desc, &usage_main());
                                }
                            };
                        }
                        match c {
                            't' => match v.parse::<usize>() {
                                Ok(n) => global.threads = n,
                                Err(e) => {
                                    return ArgResult::Err(ClapError {
                                        msg: format!(
                                            "error: invalid value '{}' for '--threads <THREADS>': {}",
                                            v, e
                                        ),
                                        usage: String::new(),
                                        help_hint: true,
                                        exit_code: 2,
                                    });
                                }
                            },
                            'f' => match Format::parse(&v) {
                                Some(f) => global.format = f,
                                None => {
                                    return ArgResult::Err(ClapError {
                                        msg: format!(
                                            "error: invalid value '{}' for '--format <FORMAT>'\n  [possible values: metric, binary, bytes, gb, gib, mb, mib]",
                                            v
                                        ),
                                        usage: String::new(),
                                        help_hint: true,
                                        exit_code: 2,
                                    });
                                }
                            },
                            'i' => {
                                explicit_ignore_dirs
                                    .get_or_insert_with(Vec::new)
                                    .push(PathBuf::from(v));
                            }
                            _ => unreachable!(),
                        }
                    }
                    _ => {
                        return err_unexpected(&format!("-{}", c), &usage_main());
                    }
                }
            }
            continue;
        }
        // Positional argument: potentially subcommand
        if subcommand_detected.is_none() {
            match a.as_str() {
                "interactive" | "i" => {
                    subcommand_detected = Some("interactive".to_string());
                    continue;
                }
                "aggregate" | "a" => {
                    subcommand_detected = Some("aggregate".to_string());
                    continue;
                }
                "completions" => {
                    subcommand_detected = Some("completions".to_string());
                    continue;
                }
                "help" => {
                    subcommand_detected = Some("help".to_string());
                    continue;
                }
                _ => {}
            }
        }
        positional.push(arg);
    }

    if let Some(v) = explicit_ignore_dirs {
        global.ignore_dirs = v;
    }

    // Now handle subcommand-specific arg parsing. Re-use `it` if not
    // consumed, plus already collected positionals.
    // Remaining args after detection loop: positional + remaining iterator
    let mut remaining: Vec<OsString> = Vec::new();
    remaining.extend(positional);
    remaining.extend(it);

    match subcommand_detected.as_deref() {
        Some("help") => {
            // Handle help subcommand
            // Skip any leading global flags we already consumed; the next
            // positional is the subcommand name.
            let sub_name = remaining
                .iter()
                .find_map(|s| s.to_str().map(|s| s.to_string()));
            return handle_help_subcommand(sub_name.as_deref(), exe_basename);
        }
        Some("completions") => {
            return parse_completions(&remaining, exe_basename);
        }
        Some("interactive") => {
            return parse_interactive(global, &remaining, exe_basename);
        }
        Some("aggregate") | None => {
            return parse_aggregate(global, &remaining, exe_basename);
        }
        _ => unreachable!(),
    }
}

fn handle_help_subcommand(sub: Option<&str>, exe_basename: &str) -> ArgResult {
    use crate::cli::{help_aggregate_full, help_completions_full, help_interactive_full, HELP_MAIN};
    match sub {
        None => ArgResult::Help(HELP_MAIN.to_string()),
        Some("interactive") | Some("i") => ArgResult::Help(help_interactive_full(exe_basename)),
        Some("aggregate") | Some("a") => ArgResult::Help(help_aggregate_full(exe_basename)),
        Some("completions") => ArgResult::Help(help_completions_full(exe_basename)),
        Some("help") => ArgResult::Help(HELP_MAIN.to_string()),
        Some(other) => ArgResult::Err(ClapError {
            msg: format!("error: unrecognized subcommand '{}'", other),
            usage: crate::cli::usage_main(),
            help_hint: true,
            exit_code: 2,
        }),
    }
}

fn parse_completions(remaining: &[OsString], exe_basename: &str) -> ArgResult {
    use crate::cli::{help_completions_full, help_completions_short, usage_completions};
    let mut shell: Option<Shell> = None;
    let mut positional: Vec<String> = Vec::new();
    let mut it = remaining.iter().cloned();
    let mut after_dd = false;
    while let Some(a) = it.next() {
        if after_dd {
            positional.push(a.to_string_lossy().to_string());
            continue;
        }
        let s = a.to_string_lossy().to_string();
        if s == "--" {
            after_dd = true;
            continue;
        }
        if s == "--help" {
            return ArgResult::Help(help_completions_full(exe_basename));
        }
        if s == "-h" {
            return ArgResult::Help(help_completions_short(exe_basename));
        }
        if s.starts_with('-') && s.len() > 1 {
            return ArgResult::Err(ClapError {
                msg: format!("error: unexpected argument '{}' found", s),
                usage: usage_completions(exe_basename),
                help_hint: true,
                exit_code: 2,
            });
        }
        positional.push(s);
    }
    if positional.is_empty() {
        return ArgResult::Err(ClapError {
            msg: "error: the following required arguments were not provided:\n  <SHELL>"
                .to_string(),
            usage: usage_completions(exe_basename),
            help_hint: true,
            exit_code: 2,
        });
    }
    if positional.len() > 1 {
        return ArgResult::Err(ClapError {
            msg: format!(
                "error: unexpected argument '{}' found",
                positional[1]
            ),
            usage: usage_completions(exe_basename),
            help_hint: true,
            exit_code: 2,
        });
    }
    shell = Shell::parse(&positional[0]);
    match shell {
        Some(s) => ArgResult::Parsed(ParsedArgs {
            global: GlobalArgs::default(),
            command: Command::Completions(s),
        }),
        None => ArgResult::Err(ClapError {
            msg: format!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]",
                positional[0]
            ),
            usage: String::new(),
            help_hint: true,
            exit_code: 2,
        }),
    }
}

fn parse_interactive(
    global: GlobalArgs,
    remaining: &[OsString],
    exe_basename: &str,
) -> ArgResult {
    use crate::cli::{help_interactive_full, help_interactive_short, usage_interactive};
    let mut a = InteractiveArgs {
        no_entry_check: false,
        input: Vec::new(),
    };
    let mut it = remaining.iter().cloned();
    let mut after_dd = false;
    while let Some(arg) = it.next() {
        if after_dd {
            a.input.push(PathBuf::from(arg));
            continue;
        }
        let s = arg.to_string_lossy().to_string();
        if s == "--" {
            after_dd = true;
            continue;
        }
        if s == "--help" {
            return ArgResult::Help(help_interactive_full(exe_basename));
        }
        if s == "-h" {
            return ArgResult::Help(help_interactive_short(exe_basename));
        }
        if s == "--no-entry-check" {
            a.no_entry_check = true;
            continue;
        }
        if s.starts_with("--") {
            return ArgResult::Err(ClapError {
                msg: format!("error: unexpected argument '{}' found", s),
                usage: usage_interactive(exe_basename),
                help_hint: true,
                exit_code: 2,
            });
        }
        if let Some(rest) = s.strip_prefix('-') {
            if rest.is_empty() {
                a.input.push(PathBuf::from(arg));
                continue;
            }
            for c in rest.chars() {
                match c {
                    'e' => a.no_entry_check = true,
                    'h' => return ArgResult::Help(help_interactive_short(exe_basename)),
                    _ => {
                        return ArgResult::Err(ClapError {
                            msg: format!("error: unexpected argument '-{}' found", c),
                            usage: usage_interactive(exe_basename),
                            help_hint: true,
                            exit_code: 2,
                        });
                    }
                }
            }
            continue;
        }
        a.input.push(PathBuf::from(arg));
    }
    ArgResult::Parsed(ParsedArgs {
        global,
        command: Command::Interactive(a),
    })
}

fn parse_aggregate(
    global: GlobalArgs,
    remaining: &[OsString],
    exe_basename: &str,
) -> ArgResult {
    use crate::cli::{help_aggregate_full, help_aggregate_short, usage_aggregate};
    let mut a = AggregateArgs {
        stats: false,
        no_sort: false,
        no_total: false,
        input: Vec::new(),
    };
    let mut it = remaining.iter().cloned();
    let mut after_dd = false;
    while let Some(arg) = it.next() {
        if after_dd {
            a.input.push(PathBuf::from(arg));
            continue;
        }
        let s = arg.to_string_lossy().to_string();
        if s == "--" {
            after_dd = true;
            continue;
        }
        if s == "--help" {
            return ArgResult::Help(help_aggregate_full(exe_basename));
        }
        if s == "-h" {
            return ArgResult::Help(help_aggregate_short(exe_basename));
        }
        if s == "--stats" {
            a.stats = true;
            continue;
        }
        if s == "--no-sort" {
            a.no_sort = true;
            continue;
        }
        if s == "--no-total" {
            a.no_total = true;
            continue;
        }
        if s.starts_with("--") {
            return ArgResult::Err(ClapError {
                msg: format!("error: unexpected argument '{}' found", s),
                usage: usage_aggregate(exe_basename),
                help_hint: true,
                exit_code: 2,
            });
        }
        if let Some(rest) = s.strip_prefix('-') {
            if rest.is_empty() {
                a.input.push(PathBuf::from(arg));
                continue;
            }
            for c in rest.chars() {
                match c {
                    'h' => return ArgResult::Help(help_aggregate_short(exe_basename)),
                    _ => {
                        return ArgResult::Err(ClapError {
                            msg: format!("error: unexpected argument '-{}' found", c),
                            usage: usage_aggregate(exe_basename),
                            help_hint: true,
                            exit_code: 2,
                        });
                    }
                }
            }
            continue;
        }
        a.input.push(PathBuf::from(arg));
    }
    ArgResult::Parsed(ParsedArgs {
        global,
        command: Command::Aggregate(a),
    })
}

fn err_missing_value(desc: &str, usage: &str) -> ArgResult {
    ArgResult::Err(ClapError {
        msg: format!(
            "error: a value is required for '{}' but none was supplied",
            desc
        ),
        usage: String::new(),
        help_hint: true,
        exit_code: 2,
    })
}

fn err_no_value(flag: &str, usage: &str) -> ArgResult {
    ArgResult::Err(ClapError {
        msg: format!("error: unexpected value for flag '{}'", flag),
        usage: usage.to_string(),
        help_hint: true,
        exit_code: 2,
    })
}

fn err_unexpected(arg: &str, usage: &str) -> ArgResult {
    // Matches: error: unexpected argument '--foo' found
    //         \n  tip: to pass '--foo' as a value, use '-- --foo'
    let tip = format!(
        "\n\n  tip: to pass '{}' as a value, use '-- {}'",
        arg, arg
    );
    ArgResult::Err(ClapError {
        msg: format!("error: unexpected argument '{}' found{}", arg, tip),
        usage: usage.to_string(),
        help_hint: true,
        exit_code: 2,
    })
}
