pub fn run(argv: Vec<OsString>) -> Result<u8, String> {
    let exe_basename = argv
        .first()
        .and_then(|a| Path::new(a).file_name().map(|n| n.to_string_lossy().to_string()))
        .unwrap_or_else(|| "dua".to_string());

    match args::parse(&argv, &exe_basename) {
        ArgResult::Help(text) => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(text.as_bytes());
            Ok(0)
        }
        ArgResult::Version(text) => {
            println!("{}", text);
            Ok(0)
        }
        ArgResult::Err(e) => {
            emit_clap_error(&e);
            Ok(e.exit_code)
        }
        ArgResult::Parsed(parsed) => dispatch(parsed, &exe_basename),
    }
}

fn emit_clap_error(e: &ClapError) {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(stderr, "{}\n", e.msg);
    if !e.usage.is_empty() {
        let _ = writeln!(stderr, "{}\n", e.usage);
    }
    if e.help_hint {
        let _ = writeln!(stderr, "For more information, try '--help'.");
    }
}

fn dispatch(parsed: ParsedArgs, exe: &str) -> Result<u8, String> {
    let ParsedArgs { global, command } = parsed;
    match command {
        Command::Completions(sh) => {
            let text = match sh {
                Shell::Bash => completions::BASH,
                Shell::Zsh => completions::ZSH,
                Shell::Fish => completions::FISH,
                Shell::Elvish => completions::ELVISH,
                Shell::Powershell => completions::POWERSHELL,
            };
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(text.as_bytes());
            Ok(0)
        }
        Command::Interactive(_iargs) => {
            // Our implementation never provides a TUI: produce the same
            // "not-a-terminal" error as the original binary when it cannot
            // initialize a TTY.
            eprintln!("Error: Interactive mode requires a connected terminal");
            Ok(1)
        }
        Command::Aggregate(aargs) => traverse::run_aggregate(&global, aargs),
    }
}
