//! Formatting routines for byte counts.

use crate::args::Format;

/// Format `value` according to `format`. Returns the pre-color string
/// that should be right-padded to the column width expected by dua.
pub fn format_bytes(value: u128, format: Format) -> String {
    match format {
        Format::Bytes => format_bytes_raw(value),
        Format::Binary => format_adaptive(value, 1024, &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"], 7, 3),
        Format::Metric => format_adaptive(value, 1000, &["B", "KB", "MB", "GB", "TB", "PB", "EB"], 7, 2),
        Format::Gb => format_fixed(value, 1_000_000_000u128, "GB", 7, 2),
        Format::Gib => format_fixed(value, 1u128 << 30, "GiB", 6, 3),
        Format::Mb => format_fixed(value, 1_000_000u128, "MB", 9, 2),
        Format::Mib => format_fixed(value, 1u128 << 20, "MiB", 8, 3),
    }
}

/// "Bytes" format: integer in a right-padded field of width >= 10.
fn format_bytes_raw(value: u128) -> String {
    let num = value.to_string();
    let num_width = num.len().max(10);
    format!("{:>width$} b", num, width = num_width)
}

/// Adaptive formatting (binary/metric): pick the largest unit `n` where
/// `value > base^n` and render using that unit.
fn format_adaptive(value: u128, base: u128, units: &[&str], num_width: usize, unit_width: usize) -> String {
    let mut n = 0usize;
    let mut threshold: u128 = base;
    // Find highest n where value > base^n (capped to available units).
    while n + 1 < units.len() && value > threshold {
        n += 1;
        // Guard against overflow
        threshold = threshold.saturating_mul(base);
    }
    let unit = units[n];
    if n == 0 {
        // Render as integer with " B" padded to unit_width
        let num = value.to_string();
        let num_s = format!("{:>width$}", num, width = num_width);
        format!("{} {:>uw$}", num_s, unit, uw = unit_width)
    } else {
        // Render as x.xx where x = value / base^n
        let divisor = threshold / base; // = base^n
        let whole = (value / divisor) as f64;
        let frac = (value % divisor) as f64 / divisor as f64;
        let num_val = whole + frac;
        let num = format!("{:.2}", num_val);
        let num_s = format!("{:>width$}", num, width = num_width);
        format!("{} {:>uw$}", num_s, unit, uw = unit_width)
    }
}

/// Fixed unit formatting (GB/MB/GiB/MiB).
fn format_fixed(value: u128, divisor: u128, unit: &str, num_width: usize, unit_width: usize) -> String {
    // For fixed units, always render as x.xx.
    let whole = (value / divisor) as f64;
    let frac = (value % divisor) as f64 / divisor as f64;
    let num_val = whole + frac;
    let num = format!("{:.2}", num_val);
    let num_s = format!("{:>width$}", num, width = num_width);
    format!("{} {:>uw$}", num_s, unit, uw = unit_width)
}

pub fn column_width(format: Format) -> usize {
    match format {
        Format::Bytes => 12,    // "         X b" minimum width (10 digits + " b")
        Format::Binary => 11,   // 7 + 1 + 3
        Format::Metric => 10,   // 7 + 1 + 2
        Format::Gb => 10,       // 7 + 1 + 2
        Format::Gib => 10,      // 6 + 1 + 3
        Format::Mb => 12,       // 9 + 1 + 2
        Format::Mib => 12,      // 8 + 1 + 3
    }
}
