//! File system traversal and aggregate output.

use std::collections::HashSet;
use std::fs::{self, Metadata};
use std::io::{self, Write};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use crate::args::{AggregateArgs, Format, GlobalArgs};
use crate::color::{cyan, green};
use crate::fmt::{column_width, format_bytes};

/// One result from traversing a single input.
struct Entry {
    display: String,
    size: u128,
    is_dir: bool,
    errors: u64,
}

pub fn run_aggregate(global: &GlobalArgs, args: AggregateArgs) -> Result<u8, String> {
    // If no inputs provided, treat like the implicit "cwd aggregate": list
    // the entries of `.` (their names) as inputs. The original binary does
    // the same by iterating the current working directory.
    let (inputs, inputs_from_cwd) = if args.input.is_empty() {
        let cwd_entries = list_cwd_entries();
        (cwd_entries, true)
    } else {
        (args.input.clone(), false)
    };

    let single_dir_expand = inputs.len() == 1 && {
        let p = &inputs[0];
        match std::fs::symlink_metadata(p) {
            Ok(m) => m.is_dir(),
            Err(_) => false,
        }
    };

    let mut stats_entries_traversed: u64 = 0;
    let mut stats_smallest: Option<u128> = None;
    let mut stats_largest: Option<u128> = None;

    // Canonicalize ignore dirs
    let ignore_dirs: Vec<PathBuf> = global
        .ignore_dirs
        .iter()
        .filter_map(|p| std::fs::canonicalize(p).ok())
        .collect();

    let mut entries: Vec<Entry> = Vec::new();

    if single_dir_expand && !inputs_from_cwd {
        // Expand single directory into its child entries as separate rows
        let root = &inputs[0];
        let children = read_dir_sorted(root);
        for child in children {
            let mut ctx = TraverseCtx::new(global, &ignore_dirs);
            let meta = std::fs::symlink_metadata(&child);
            let (size, is_dir, errors) = match meta {
                Ok(m) => walk_with_base(&child, &m, &mut ctx),
                Err(_) => (0u128, false, 1u64),
            };
            stats_entries_traversed += ctx.entries_traversed;
            if let Some(min) = ctx.smallest_file {
                stats_smallest = Some(stats_smallest.map_or(min, |cur| cur.min(min)));
            }
            if let Some(max) = ctx.largest_file {
                stats_largest = Some(stats_largest.map_or(max, |cur| cur.max(max)));
            }
            let display = display_for(&child, Some(root));
            entries.push(Entry {
                display,
                size,
                is_dir,
                errors,
            });
        }
    } else {
        for path in &inputs {
            let mut ctx = TraverseCtx::new(global, &ignore_dirs);
            let meta = std::fs::symlink_metadata(path);
            let (size, is_dir, errors) = match meta {
                Ok(m) => {
                    if m.file_type().is_symlink() && !inputs_from_cwd {
                        // Explicitly passed symlink: 1 IO error
                        (0u128, false, 1u64)
                    } else if m.file_type().is_symlink() && inputs_from_cwd {
                        // Symlinks from cwd listing are silently skipped
                        continue;
                    } else {
                        walk_with_base(path, &m, &mut ctx)
                    }
                }
                Err(_) => (0u128, false, 1u64),
            };
