    let mut stdout = io::stdout().lock();
    let col = column_width(global.format);

    for e in &entries {
        let s = format_bytes(e.size, global.format);
        let pad = col.saturating_sub(visible_len(&s));
        let name_part = if e.is_dir {
            cyan(&e.display)
        } else {
            e.display.clone()
        };
        let err_suffix = if e.errors > 0 {
            format!("  <{} IO Error>", e.errors)
        } else {
            String::new()
        };
        let _ = writeln!(
            stdout,
            "{}{} {}{}",
            " ".repeat(pad),
            green(&s),
            name_part,
            err_suffix
        );
    }

    if show_total {
        let s = format_bytes(total_size, global.format);
        let pad = col.saturating_sub(visible_len(&s));
        let err_suffix = if total_errors > 0 {
            format!("  <{} IO Error>", total_errors)
        } else {
            String::new()
        };
        let _ = writeln!(
            stdout,
            "{}{} total{}",
            " ".repeat(pad),
            green(&s),
            err_suffix
        );
