        let _ = writeln!(
            stderr,
            "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
            stats_entries_traversed,
            stats_smallest.unwrap_or(0),
            stats_largest.unwrap_or(0)
        );
    }

    Ok(0)
}

fn visible_len(s: &str) -> usize {
    // Pre-color string has no ANSI codes.
    s.chars().count()
}

fn list_cwd_entries() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = fs::read_dir(".") {
        for entry in rd.flatten() {
            out.push(entry.file_name().into());
        }
    }
    out.sort();
    out
}

fn read_dir_sorted(p: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = fs::read_dir(p)
        .into_iter()
        .flat_map(|rd| rd.flatten().map(|e| e.path()))
        .collect();
    v.sort();
    v
}

fn display_for(path: &Path, strip_prefix: Option<&Path>) -> String {
    let s = match strip_prefix {
        Some(base) => match path.strip_prefix(base) {
            Ok(rest) => rest.to_path_buf(),
            Err(_) => path.to_path_buf(),
        },
        None => path.to_path_buf(),
    };
    s.to_string_lossy().into_owned()
}

struct TraverseCtx<'a> {
    global: &'a GlobalArgs,
    ignore_dirs: &'a [PathBuf],
    seen_hardlinks: HashSet<(u64, u64)>, // (dev, inode)
    root_dev: Option<u64>,
    entries_traversed: u64,
    smallest_file: Option<u128>,
    largest_file: Option<u128>,
}

impl<'a> TraverseCtx<'a> {
    fn new(global: &'a GlobalArgs, ignore_dirs: &'a [PathBuf]) -> Self {
        TraverseCtx {
            global,
            ignore_dirs,
            seen_hardlinks: HashSet::new(),
            root_dev: None,
            entries_traversed: 0,
            smallest_file: None,
            largest_file: None,
        }
    }

    fn observe(&mut self, len: u128) {
        self.entries_traversed += 1;
        self.smallest_file = Some(match self.smallest_file {
            Some(s) => s.min(len),
            None => len,
        });
        self.largest_file = Some(match self.largest_file {
            Some(s) => s.max(len),
            None => len,
        });
    }
}

fn walk_with_base(path: &Path, meta: &Metadata, ctx: &mut TraverseCtx) -> (u128, bool, u64) {
    if ctx.root_dev.is_none() {
        ctx.root_dev = Some(meta.dev());
    }
    let ignore = ctx
        .ignore_dirs
        .iter()
        .any(|d| paths_equal_canonical(path, d));
    if ignore {
        // Ignored: zero size, no error
        return (0u128, meta.is_dir(), 0);
    }
    walk(path, meta, ctx, false)
}

fn paths_equal_canonical(a: &Path, b: &Path) -> bool {
    match std::fs::canonicalize(a) {
        Ok(ca) => ca == *b,
        Err(_) => false,
    }
}

fn walk(path: &Path, meta: &Metadata, ctx: &mut TraverseCtx, is_child: bool) -> (u128, bool, u64) {
    let ft = meta.file_type();
    if ft.is_symlink() {
        // Symlinks encountered during recursion are not followed and
        // contribute 0 bytes. The top-level caller decides whether they are
        // errors.
        ctx.observe(0);
        return (0u128, false, 0);
    }
    if ft.is_file() {
        // Hard-link handling
        if !ctx.global.count_hard_links {
            let key = (meta.dev(), meta.ino());
            if meta.nlink() > 1 {
                if ctx.seen_hardlinks.contains(&key) {
                    ctx.observe(0);
                    return (0u128, false, 0);
                }
                ctx.seen_hardlinks.insert(key);
            }
        }
        let size = size_of(meta, ctx.global.apparent_size);
        ctx.observe(size);
        return (size, false, 0);
    }
    if ft.is_dir() {
        // Respect stay-on-filesystem.
        if is_child && ctx.global.stay_on_filesystem {
            if let Some(root) = ctx.root_dev {
                if meta.dev() != root {
                    return (0u128, true, 0);
                }
            }
        }
        let mut total: u128 = if ctx.global.apparent_size {
            // Include directory's own apparent size in sum.
            size_of(meta, true)
        } else {
            size_of(meta, false)
        };
        let mut errors: u64 = 0;
        let rd = match fs::read_dir(path) {
            Ok(rd) => rd,
            Err(_) => {
                return (0u128, true, 1);
            }
        };
        for child in rd.flatten() {
            let cpath = child.path();
            // Check ignore-dirs
            let ignore = ctx
                .ignore_dirs
                .iter()
                .any(|d| paths_equal_canonical(&cpath, d));
            if ignore {
                continue;
            }
            let cmeta = match child.metadata_no_follow() {
                Ok(m) => m,
                Err(_) => {
                    errors += 1;
                    continue;
                }
            };
            let (sz, _is_dir, err) = walk(&cpath, &cmeta, ctx, true);
            total = total.saturating_add(sz);
            errors = errors.saturating_add(err);
        }
        return (total, true, errors);
    }
    // Other types (block, char, socket, fifo): ignore
    (0u128, false, 0)
}

fn size_of(meta: &Metadata, apparent: bool) -> u128 {
    if apparent {
        meta.len() as u128
    } else {
        (meta.blocks() as u128) * 512
    }
}

// Helper trait to fetch metadata without following symlinks via DirEntry.
trait DirEntryExt {
    fn metadata_no_follow(&self) -> io::Result<Metadata>;
}
impl DirEntryExt for fs::DirEntry {
    fn metadata_no_follow(&self) -> io::Result<Metadata> {
        // On unix, DirEntry::metadata follows the link; we need
        // symlink_metadata to avoid that.
        std::fs::symlink_metadata(self.path())
    }
}
