//! File system traversal and aggregate output.

use std::collections::HashSet;
use std::fs::{self, Metadata};
use std::io::{self, Write};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use crate::args::{AggregateArgs, GlobalArgs};
use crate::color::{cyan, green};
use crate::fmt::{column_width, format_bytes};

struct Entry {
    display: String,
    size: u128,
    /// True if the name should be colored as a directory. For broken symlinks
    /// or missing paths, the original program also renders the name in cyan.
    cyan_name: bool,
    errors: u64,
}

pub fn run_aggregate(global: &GlobalArgs, args: AggregateArgs) -> Result<u8, String> {
    let (inputs, inputs_from_cwd) = if args.input.is_empty() {
        (list_cwd_entries(), true)
    } else {
        (args.input.clone(), false)
    };

    // If exactly one explicit directory, list its contents.
    let single_dir_expand = inputs.len() == 1 && {
        let p = &inputs[0];
        match std::fs::symlink_metadata(p) {
            Ok(m) => m.is_dir(),
            Err(_) => false,
        }
    };

    let ignore_dirs: Vec<PathBuf> = global
        .ignore_dirs
        .iter()
        .filter_map(|p| std::fs::canonicalize(p).ok())
        .collect();

    let mut ctx = TraverseCtx::new(global, &ignore_dirs);

    let mut entries: Vec<Entry> = Vec::new();

    let roots: Vec<(PathBuf, Option<PathBuf>)> = if single_dir_expand && !inputs_from_cwd {
        let root = inputs[0].clone();
        let children = read_dir_sorted(&root);
        children
            .into_iter()
            .map(|c| (c, Some(root.clone())))
            .collect()
    } else {
        inputs.iter().map(|p| (p.clone(), None)).collect()
    };

    for (path, base) in &roots {
        // When iterating cwd entries or child of a single-dir expansion,
        // silently skip symlinks.
        let from_listing = inputs_from_cwd || base.is_some();

        let lmeta = std::fs::symlink_metadata(path);
        let (size, cyan_name, errors) = match lmeta {
            Ok(m) => {
                let ft = m.file_type();
                if ft.is_symlink() {
                    if from_listing {
                        continue;
                    }
                    handle_top_level_symlink(path, &m, &mut ctx)
                } else {
                    let (sz, is_dir, err) = walk_root(path, &m, &mut ctx);
                    (sz, is_dir, err)
                }
            }
            Err(_) => (0u128, true, 1u64),
        };

        let display = display_for(path, base.as_deref());
        entries.push(Entry {
            display,
            size,
            cyan_name,
            errors,
        });
    }

    if !args.no_sort {
        entries.sort_by(|a, b| a.size.cmp(&b.size));
    }

    let show_total = !args.no_total && entries.len() > 1;
    let total_size: u128 = entries.iter().map(|e| e.size).sum();
    let total_errors: u64 = entries.iter().map(|e| e.errors).sum();

    let mut stdout = io::stdout().lock();
    let col = column_width(global.format);

    for e in &entries {
        let s = format_bytes(e.size, global.format);
        let pad = col.saturating_sub(visible_len(&s));
        let name_part = if e.cyan_name {
            cyan(&e.display)
        } else {
            e.display.clone()
        };
        let err_suffix = if e.errors > 0 {
            format!("  <{} IO Error>", e.errors)
        } else {
            String::new()
        };
        let _ = writeln!(
            stdout,
            "{}{} {}{}",
            " ".repeat(pad),
            green(&s),
            name_part,
            err_suffix
        );
    }

    if show_total {
        let s = format_bytes(total_size, global.format);
        let pad = col.saturating_sub(visible_len(&s));
        let err_suffix = if total_errors > 0 {
            format!("  <{} IO Error>", total_errors)
        } else {
            String::new()
        };
        let _ = writeln!(
            stdout,
            "{}{} total{}",
            " ".repeat(pad),
            green(&s),
            err_suffix
        );
    }

    if args.stats {
        let mut stderr = io::stderr().lock();
        let _ = writeln!(
            stderr,
            "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
            ctx.entries_traversed,
            ctx.smallest_file.unwrap_or(0),
            ctx.largest_file.unwrap_or(0)
        );
    }

    Ok(0)
}

fn visible_len(s: &str) -> usize {
    s.chars().count()
}

fn list_cwd_entries() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = fs::read_dir(".") {
        for entry in rd.flatten() {
            out.push(PathBuf::from(entry.file_name()));
        }
    }
    out.sort();
    out
}

fn read_dir_sorted(p: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = fs::read_dir(p)
        .into_iter()
        .flat_map(|rd| rd.flatten().map(|e| e.path()))
        .collect();
    v.sort();
    v
}

fn display_for(path: &Path, strip_prefix: Option<&Path>) -> String {
    let s = match strip_prefix {
        Some(base) => match path.strip_prefix(base) {
            Ok(rest) => rest.to_path_buf(),
            Err(_) => path.to_path_buf(),
        },
        None => path.to_path_buf(),
    };
    s.to_string_lossy().into_owned()
}

struct TraverseCtx<'a> {
