}

fn paths_equal_canonical(a: &Path, b: &Path) -> bool {
    std::fs::canonicalize(a).map(|ca| ca == *b).unwrap_or(false)
}

fn walk(path: &Path, meta: &Metadata, ctx: &mut TraverseCtx, is_child: bool) -> (u128, bool, u64) {
    let ft = meta.file_type();
    if ft.is_symlink() {
