            }
        }
        let size = size_of(meta, ctx.global.apparent_size);
        ctx.observe(size);
        return (size, false, 0);
    }
    if ft.is_dir() {
        if is_child && ctx.global.stay_on_filesystem {
            if let Some(root) = ctx.root_dev {
                if meta.dev() != root {
